// Generated by scripts/sync-registry.mjs from components/registry. Do not edit by hand.
export const registrySources: Record<string, string> = {
  "animated-checklist": "'use client';\nimport { useState } from 'react';\n\nconst initialTasks = [\n  { id: 'brief', label: 'Write the product brief', done: true },\n  { id: 'wireframes', label: 'Review wireframes', done: false },\n  { id: 'launch', label: 'Schedule the launch', done: false },\n];\n\nexport function AnimatedChecklist() {\n  const [tasks, setTasks] = useState(initialTasks);\n  const doneCount = tasks.filter((task) => task.done).length;\n\n  return (\n    <div className=\"w-full max-w-sm rounded-3xl border border-zinc-200 bg-white p-5 shadow-sm dark:border-zinc-800 dark:bg-zinc-950\">\n      <div className=\"flex items-center justify-between\">\n        <p className=\"font-semibold text-zinc-900 dark:text-white\">Launch week</p>\n        <span className=\"text-xs font-medium text-zinc-500 dark:text-zinc-400\">{doneCount}/{tasks.length} done</span>\n      </div>\n      <ul className=\"mt-4 space-y-1\">\n        {tasks.map((task) => (\n          <li key={task.id}>\n            <label className=\"group flex cursor-pointer items-center gap-3 rounded-2xl px-2 py-2.5 transition hover:bg-zinc-100 dark:hover:bg-zinc-900\">\n              <input\n                type=\"checkbox\"\n                checked={task.done}\n                onChange={() => setTasks((current) => current.map((item) => (item.id === task.id ? { ...item, done: !item.done } : item)))}\n                className=\"peer sr-only\"\n              />\n              <span className=\"grid size-6 shrink-0 place-items-center rounded-lg border-2 border-zinc-300 transition peer-checked:border-teal-500 peer-checked:bg-teal-500 peer-focus-visible:ring-4 peer-focus-visible:ring-teal-500/25 dark:border-zinc-600 [&>svg>path]:[stroke-dasharray:16] [&>svg>path]:[stroke-dashoffset:16] peer-checked:[&>svg>path]:[stroke-dashoffset:0]\">\n                {/* The check is drawn by animating the stroke offset. */}\n                <svg viewBox=\"0 0 16 16\" className=\"size-3.5\" aria-hidden>\n                  <path d=\"M3 8.5l3.2 3L13 5\" fill=\"none\" stroke=\"white\" strokeWidth=\"2.4\" strokeLinecap=\"round\" strokeLinejoin=\"round\" className=\"transition-[stroke-dashoffset] duration-300 ease-out\" />\n                </svg>\n              </span>\n              <span className=\"relative text-sm text-zinc-800 transition-colors peer-checked:text-zinc-400 dark:text-zinc-200 dark:peer-checked:text-zinc-500\">\n                {task.label}\n                <span aria-hidden className={`absolute left-0 top-1/2 h-px bg-current transition-all duration-300 ${task.done ? 'w-full' : 'w-0'}`} />\n              </span>\n            </label>\n          </li>\n        ))}\n      </ul>\n    </div>\n  );\n}",
  "bento-features": "import { Layers, ShieldCheck, Sparkles, Zap } from 'lucide-react';\n\nexport function BentoFeatures() {\n  return (\n    <section className=\"grid w-full max-w-3xl gap-3 sm:grid-cols-3\">\n      <article className=\"relative overflow-hidden rounded-3xl bg-zinc-950 p-6 text-white sm:col-span-2 dark:bg-white dark:text-zinc-950\">\n        <div aria-hidden className=\"absolute -right-10 -top-10 size-40 rounded-full bg-teal-400/30 blur-3xl\" />\n        <Sparkles aria-hidden className=\"relative size-5 text-teal-300 dark:text-teal-600\" />\n        <h3 className=\"relative mt-8 text-2xl font-semibold tracking-tight\">Prompt to production</h3>\n        <p className=\"relative mt-2 max-w-sm text-sm leading-6 text-zinc-400 dark:text-zinc-600\">\n          Describe the screen, get typed React you actually own.\n        </p>\n      </article>\n      <article className=\"rounded-3xl border border-zinc-200 bg-white p-6 dark:border-zinc-800 dark:bg-zinc-950\">\n        <Zap aria-hidden className=\"size-5 text-amber-500\" />\n        <p className=\"mt-8 text-4xl font-semibold tracking-tight text-zinc-900 dark:text-white\">3×</p>\n        <p className=\"mt-1 text-sm text-zinc-600 dark:text-zinc-400\">faster first release</p>\n      </article>\n      <article className=\"rounded-3xl border border-zinc-200 bg-white p-6 dark:border-zinc-800 dark:bg-zinc-950\">\n        <ShieldCheck aria-hidden className=\"size-5 text-emerald-500\" />\n        <h3 className=\"mt-8 font-semibold text-zinc-900 dark:text-white\">Accessible by default</h3>\n        <p className=\"mt-1 text-sm text-zinc-600 dark:text-zinc-400\">Focus, roles and contrast built in.</p>\n      </article>\n      <article className=\"rounded-3xl bg-gradient-to-br from-violet-500 to-teal-400 p-6 text-white sm:col-span-2\">\n        <Layers aria-hidden className=\"size-5\" />\n        <div className=\"mt-6 flex flex-wrap gap-2\">\n          {['Hero', 'Pricing', 'Dashboard', 'Auth', 'Chat'].map((tag) => (\n            <span key={tag} className=\"rounded-full bg-white/20 px-3 py-1 text-xs font-semibold backdrop-blur\">{tag}</span>\n          ))}\n        </div>\n        <p className=\"mt-3 text-sm font-medium text-white/90\">120+ blocks, one design language.</p>\n      </article>\n    </section>\n  );\n}",
  "border-beam-button": "import { Sparkles } from 'lucide-react';\n\nexport function BorderBeamButton() {\n  return (\n    <>\n      <style>{`@keyframes pui-beam{to{transform:rotate(360deg)}}`}</style>\n      <button\n        type=\"button\"\n        className=\"group relative inline-flex overflow-hidden rounded-full bg-zinc-200 p-px shadow-sm transition active:scale-[.97] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-violet-500 focus-visible:ring-offset-2 dark:bg-zinc-800 dark:focus-visible:ring-offset-zinc-950\"\n      >\n        {/* Oversized conic gradient spinning behind a 1px gap: reads as a light running along the border. */}\n        <span\n          aria-hidden\n          className=\"absolute inset-[-150%] bg-[conic-gradient(from_0deg,transparent_0_65%,#2dd4bf_78%,#a78bfa_90%,transparent_100%)] motion-safe:animate-[pui-beam_3.2s_linear_infinite]\"\n        />\n        <span className=\"relative inline-flex h-11 items-center gap-2 rounded-full bg-white px-6 text-sm font-semibold text-zinc-900 transition-colors group-hover:bg-zinc-50 dark:bg-zinc-950 dark:text-white dark:group-hover:bg-zinc-900\">\n          <Sparkles aria-hidden className=\"size-4 text-violet-500 dark:text-violet-400\" />\n          Generate with AI\n        </span>\n      </button>\n    </>\n  );\n}",
  "floating-label-input": "const fields = [\n  { id: 'fl-email', label: 'Email address', type: 'email', hint: 'We never share it.' },\n  { id: 'fl-workspace', label: 'Workspace name', type: 'text', hint: 'You can change it later.' },\n];\n\nexport function FloatingLabelInput() {\n  return (\n    <form className=\"grid w-full max-w-sm gap-4\" onSubmit={(event) => event.preventDefault()}>\n      {fields.map((field) => (\n        <div key={field.id}>\n          <div className=\"relative\">\n            {/* placeholder=\" \" lets :placeholder-shown tell us whether the field is empty. */}\n            <input\n              id={field.id}\n              type={field.type}\n              placeholder=\" \"\n              aria-describedby={`${field.id}-hint`}\n              className=\"peer h-14 w-full rounded-2xl border border-zinc-300 bg-white px-4 pt-5 text-sm text-zinc-900 outline-none transition focus:border-teal-500 focus:ring-4 focus:ring-teal-500/15 dark:border-zinc-700 dark:bg-zinc-900 dark:text-zinc-50 dark:focus:border-teal-400\"\n            />\n            <label\n              htmlFor={field.id}\n              className=\"pointer-events-none absolute left-4 top-1/2 -translate-y-1/2 text-sm text-zinc-500 transition-all peer-focus:top-4 peer-focus:text-xs peer-focus:text-teal-700 peer-[:not(:placeholder-shown)]:top-4 peer-[:not(:placeholder-shown)]:text-xs dark:text-zinc-400 dark:peer-focus:text-teal-400\"\n            >\n              {field.label}\n            </label>\n          </div>\n          <p id={`${field.id}-hint`} className=\"mt-1.5 pl-1 text-xs text-zinc-500 dark:text-zinc-400\">{field.hint}</p>\n        </div>\n      ))}\n    </form>\n  );\n}",
  "gradient-text": "export function GradientText() {\n  return (\n    <>\n      <style>{`@keyframes pui-pan{to{background-position:200% center}}`}</style>\n      <div className=\"max-w-xl text-center\">\n        <p className=\"text-xs font-semibold uppercase tracking-[.2em] text-zinc-500 dark:text-zinc-400\">Introducing</p>\n        <h2 className=\"mt-3 bg-[linear-gradient(90deg,#14b8a6,#8b5cf6,#f59e0b,#14b8a6)] bg-[length:200%_auto] bg-clip-text text-4xl font-semibold tracking-tight text-transparent motion-safe:animate-[pui-pan_6s_linear_infinite] sm:text-6xl\">\n          Design at the speed of thought\n        </h2>\n        <p className=\"mt-4 text-sm leading-6 text-zinc-600 dark:text-zinc-400\">\n          A gradient that drifts slowly across the headline, readable on light and dark surfaces.\n        </p>\n      </div>\n    </>\n  );\n}",
  "marquee-testimonials": "const quotes = [\n  { name: 'Awa Diallo', role: 'Design lead', text: 'We shipped our new onboarding in two days.' },\n  { name: 'Lucas Martin', role: 'Founder', text: 'The prompts alone saved us a sprint.' },\n  { name: 'Mei Chen', role: 'Frontend engineer', text: 'Clean code I would have written myself.' },\n  { name: 'Omar Haddad', role: 'Product manager', text: 'Our demos finally look like the real product.' },\n  { name: 'Sofia Rossi', role: 'Indie hacker', text: 'Dark mode just worked. Every single block.' },\n];\n\nfunction Row({ reverse = false }: { reverse?: boolean }) {\n  // The list is rendered twice so the -50% translation loops seamlessly.\n  return (\n    <div className=\"flex w-max gap-3 group-hover:[animation-play-state:paused] motion-safe:animate-[pui-marquee_28s_linear_infinite]\" style={{ animationDirection: reverse ? 'reverse' : 'normal' }}>\n      {[...quotes, ...quotes].map((quote, index) => (\n        <figure\n          key={index}\n          aria-hidden={index >= quotes.length}\n          className=\"w-64 shrink-0 rounded-2xl border border-zinc-200 bg-white p-4 dark:border-zinc-800 dark:bg-zinc-900\"\n        >\n          <blockquote className=\"text-sm leading-6 text-zinc-700 dark:text-zinc-300\">“{quote.text}”</blockquote>\n          <figcaption className=\"mt-3 flex items-center gap-2.5\">\n            <span className=\"grid size-8 place-items-center rounded-full bg-gradient-to-br from-teal-400 to-violet-500 text-xs font-bold text-white\">\n              {quote.name.split(' ').map((part) => part[0]).join('')}\n            </span>\n            <span>\n              <span className=\"block text-sm font-semibold text-zinc-900 dark:text-white\">{quote.name}</span>\n              <span className=\"block text-xs text-zinc-500 dark:text-zinc-400\">{quote.role}</span>\n            </span>\n          </figcaption>\n        </figure>\n      ))}\n    </div>\n  );\n}\n\nexport function MarqueeTestimonials() {\n  return (\n    <>\n      <style>{`@keyframes pui-marquee{to{transform:translateX(-50%)}}`}</style>\n      <section\n        aria-label=\"Testimonials\"\n        className=\"group grid w-full max-w-3xl gap-3 overflow-hidden [mask-image:linear-gradient(to_right,transparent,#000_12%,#000_88%,transparent)]\"\n      >\n        <Row />\n        <Row reverse />\n      </section>\n    </>\n  );\n}",
  "orbit-loader": "export function OrbitLoader() {\n  return (\n    <>\n      <style>{`@keyframes pui-orbit{to{transform:rotate(360deg)}}@keyframes pui-breathe{50%{transform:scale(.8);opacity:.6}}`}</style>\n      <div role=\"status\" className=\"flex flex-col items-center gap-5\">\n        <div className=\"relative size-20\">\n          <span className=\"absolute inset-0 rounded-full border border-zinc-200 dark:border-zinc-800\" />\n          <span className=\"absolute inset-[30%] rounded-full bg-gradient-to-br from-teal-400 to-violet-500 motion-safe:animate-[pui-breathe_1.6s_ease-in-out_infinite]\" />\n          {[\n            { color: 'bg-teal-500', duration: '1.4s', delay: '0s' },\n            { color: 'bg-violet-500', duration: '1.4s', delay: '-.47s' },\n            { color: 'bg-amber-400', duration: '1.4s', delay: '-.93s' },\n          ].map((dot) => (\n            <span\n              key={dot.color}\n              className=\"absolute inset-0 motion-safe:animate-[pui-orbit_linear_infinite]\"\n              style={{ animationDuration: dot.duration, animationDelay: dot.delay }}\n            >\n              <span className={`absolute left-1/2 top-0 size-3 -translate-x-1/2 -translate-y-1/2 rounded-full shadow-sm ${dot.color}`} />\n            </span>\n          ))}\n        </div>\n        <p className=\"text-sm font-medium text-zinc-600 dark:text-zinc-400\">Generating your layout…</p>\n      </div>\n    </>\n  );\n}",
  "otp-input": "'use client';\nimport { Check } from 'lucide-react';\nimport { useRef, useState, type ClipboardEvent, type KeyboardEvent } from 'react';\n\nconst LENGTH = 6;\n\nexport function OtpInput() {\n  const [digits, setDigits] = useState<string[]>(Array(LENGTH).fill(''));\n  const inputs = useRef<(HTMLInputElement | null)[]>([]);\n  const complete = digits.every(Boolean);\n\n  function update(index: number, value: string) {\n    const digit = value.replace(/\\D/g, '').slice(-1);\n    setDigits((current) => current.map((item, i) => (i === index ? digit : item)));\n    if (digit && index < LENGTH - 1) inputs.current[index + 1]?.focus();\n  }\n\n  function onKeyDown(index: number, event: KeyboardEvent<HTMLInputElement>) {\n    if (event.key === 'Backspace' && !digits[index] && index > 0) inputs.current[index - 1]?.focus();\n    if (event.key === 'ArrowLeft' && index > 0) inputs.current[index - 1]?.focus();\n    if (event.key === 'ArrowRight' && index < LENGTH - 1) inputs.current[index + 1]?.focus();\n  }\n\n  function onPaste(event: ClipboardEvent<HTMLInputElement>) {\n    const pasted = event.clipboardData.getData('text').replace(/\\D/g, '').slice(0, LENGTH);\n    if (!pasted) return;\n    event.preventDefault();\n    setDigits(Array.from({ length: LENGTH }, (_, i) => pasted[i] ?? ''));\n    inputs.current[Math.min(pasted.length, LENGTH - 1)]?.focus();\n  }\n\n  return (\n    <fieldset className=\"w-full min-w-0 max-w-sm rounded-3xl border border-zinc-200 bg-white p-6 text-center shadow-sm dark:border-zinc-800 dark:bg-zinc-950\">\n      <legend className=\"sr-only\">Verification code</legend>\n      <p className=\"text-lg font-semibold text-zinc-900 dark:text-white\">Check your inbox</p>\n      <p className=\"mt-1 text-sm text-zinc-600 dark:text-zinc-400\">Enter the 6-digit code we sent you.</p>\n      <div className=\"mt-6 flex justify-center gap-1.5 sm:gap-2\">\n        {digits.map((digit, index) => (\n          <input\n            key={index}\n            ref={(node) => { inputs.current[index] = node; }}\n            value={digit}\n            inputMode=\"numeric\"\n            autoComplete={index === 0 ? 'one-time-code' : 'off'}\n            maxLength={1}\n            aria-label={`Digit ${index + 1}`}\n            onChange={(event) => update(index, event.target.value)}\n            onKeyDown={(event) => onKeyDown(index, event)}\n            onPaste={onPaste}\n            onFocus={(event) => event.target.select()}\n            className={`size-10 rounded-xl border bg-white text-center text-lg font-semibold text-zinc-900 outline-none transition focus:ring-4 sm:size-11 dark:bg-zinc-900 dark:text-white ${\n              complete\n                ? 'border-emerald-500 focus:ring-emerald-500/20'\n                : 'border-zinc-300 focus:border-teal-500 focus:ring-teal-500/15 dark:border-zinc-700 dark:focus:border-teal-400'\n            }`}\n          />\n        ))}\n      </div>\n      <p role=\"status\" className={`mt-4 inline-flex items-center gap-1.5 text-sm font-medium transition-opacity ${complete ? 'text-emerald-600 opacity-100 dark:text-emerald-400' : 'opacity-0'}`}>\n        <Check aria-hidden className=\"size-4\" /> Code complete\n      </p>\n    </fieldset>\n  );\n}",
  "pricing-toggle": "'use client';\nimport { Check } from 'lucide-react';\nimport { useState } from 'react';\n\nconst plans = [\n  { name: 'Starter', monthly: 0, yearly: 0, features: ['3 projects', 'Community blocks'], highlight: false },\n  { name: 'Pro', monthly: 24, yearly: 19, features: ['Unlimited projects', 'All blocks + prompts', 'Priority support'], highlight: true },\n];\n\nexport function PricingToggle() {\n  const [yearly, setYearly] = useState(true);\n\n  return (\n    <>\n      <style>{`@keyframes pui-price{from{opacity:0;transform:translateY(-8px)}to{opacity:1;transform:none}}`}</style>\n      <section className=\"w-full max-w-2xl\">\n        <div className=\"mx-auto flex w-fit items-center rounded-full border border-zinc-200 bg-zinc-100 p-1 dark:border-zinc-800 dark:bg-zinc-900\" role=\"radiogroup\" aria-label=\"Billing period\">\n          {[['Monthly', false], ['Yearly', true]].map(([label, value]) => (\n            <button\n              key={String(label)}\n              type=\"button\"\n              role=\"radio\"\n              aria-checked={yearly === value}\n              onClick={() => setYearly(value as boolean)}\n              className={`relative rounded-full px-4 py-1.5 text-sm font-semibold transition focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-teal-500 ${\n                yearly === value ? 'bg-white text-zinc-900 shadow-sm dark:bg-zinc-700 dark:text-white' : 'text-zinc-500 hover:text-zinc-900 dark:text-zinc-400 dark:hover:text-white'\n              }`}\n            >\n              {label}\n              {value && <span className=\"ml-1.5 rounded-full bg-teal-500/15 px-1.5 py-0.5 text-[10px] text-teal-700 dark:text-teal-300\">-20%</span>}\n            </button>\n          ))}\n        </div>\n\n        <div className=\"mt-6 grid gap-3 sm:grid-cols-2\">\n          {plans.map((plan) => (\n            <article\n              key={plan.name}\n              className={`rounded-3xl p-6 ${\n                plan.highlight\n                  ? 'bg-zinc-950 text-white ring-1 ring-zinc-950 dark:bg-white dark:text-zinc-950'\n                  : 'border border-zinc-200 bg-white text-zinc-900 dark:border-zinc-800 dark:bg-zinc-950 dark:text-white'\n              }`}\n            >\n              <p className=\"text-sm font-semibold opacity-80\">{plan.name}</p>\n              <p className=\"mt-3 flex items-baseline gap-1\">\n                <span key={String(yearly)} className=\"text-4xl font-semibold tracking-tight motion-safe:animate-[pui-price_.35s_ease-out]\">\n                  ${yearly ? plan.yearly : plan.monthly}\n                </span>\n                <span className=\"text-sm opacity-60\">/mo</span>\n              </p>\n              <ul className=\"mt-5 space-y-2 text-sm\">\n                {plan.features.map((feature) => (\n                  <li key={feature} className=\"flex items-center gap-2\">\n                    <Check aria-hidden className={`size-4 ${plan.highlight ? 'text-teal-300 dark:text-teal-600' : 'text-teal-600 dark:text-teal-400'}`} />\n                    {feature}\n                  </li>\n                ))}\n              </ul>\n            </article>\n          ))}\n        </div>\n      </section>\n    </>\n  );\n}",
  "push-button": "export function PushButton() {\n  return (\n    <div className=\"flex flex-wrap items-center justify-center gap-5\">\n      {[\n        { label: 'Deploy', base: 'bg-teal-700 dark:bg-teal-800', face: 'bg-teal-500 text-white dark:bg-teal-400 dark:text-teal-950' },\n        { label: 'Cancel', base: 'bg-zinc-300 dark:bg-zinc-700', face: 'bg-white text-zinc-800 dark:bg-zinc-900 dark:text-zinc-100' },\n      ].map(({ label, base, face }) => (\n        // The darker base stays put; the face sinks onto it when pressed.\n        <button\n          key={label}\n          type=\"button\"\n          className={`group rounded-2xl outline-none focus-visible:ring-2 focus-visible:ring-teal-500 focus-visible:ring-offset-2 dark:focus-visible:ring-offset-zinc-950 ${base}`}\n        >\n          <span\n            className={`block -translate-y-1.5 rounded-2xl px-7 py-3 text-sm font-bold shadow-sm transition-transform duration-100 group-hover:-translate-y-2 group-active:translate-y-0 ${face}`}\n          >\n            {label}\n          </span>\n        </button>\n      ))}\n    </div>\n  );\n}",
  "shimmer-button": "import { ArrowRight } from 'lucide-react';\n\nexport function ShimmerButton() {\n  return (\n    <>\n      <style>{`@keyframes pui-shimmer{0%{transform:translateX(0)}60%,100%{transform:translateX(300%)}}`}</style>\n      <button\n        type=\"button\"\n        className=\"group relative inline-flex h-12 items-center gap-2 overflow-hidden rounded-full bg-zinc-950 px-7 text-sm font-semibold text-white shadow-lg shadow-zinc-950/20 transition active:scale-[.97] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-teal-500 focus-visible:ring-offset-2 dark:bg-white dark:text-zinc-950 dark:shadow-white/10 dark:focus-visible:ring-offset-zinc-950\"\n      >\n        <span\n          aria-hidden\n          className=\"absolute inset-y-0 -left-1/2 w-1/2 -skew-x-12 bg-gradient-to-r from-transparent via-white/40 to-transparent motion-safe:animate-[pui-shimmer_2.8s_ease-in-out_infinite] dark:via-teal-400/30\"\n        />\n        <span className=\"relative\">Get early access</span>\n        <ArrowRight aria-hidden className=\"relative size-4 transition-transform group-hover:translate-x-0.5\" />\n      </button>\n    </>\n  );\n}",
  "spotlight-card": "'use client';\nimport { RefreshCw } from 'lucide-react';\nimport { useState, type PointerEvent } from 'react';\n\nexport function SpotlightCard() {\n  const [spot, setSpot] = useState({ x: 0, y: 0, visible: false });\n\n  function follow(event: PointerEvent<HTMLElement>) {\n    const rect = event.currentTarget.getBoundingClientRect();\n    setSpot({ x: event.clientX - rect.left, y: event.clientY - rect.top, visible: true });\n  }\n\n  return (\n    <article\n      onPointerMove={follow}\n      onPointerLeave={() => setSpot((value) => ({ ...value, visible: false }))}\n      className=\"relative w-full max-w-sm overflow-hidden rounded-3xl border border-zinc-200 bg-white p-6 shadow-sm dark:border-zinc-800 dark:bg-zinc-950\"\n    >\n      <div\n        aria-hidden\n        className=\"pointer-events-none absolute inset-0 transition-opacity duration-300\"\n        style={{\n          opacity: spot.visible ? 1 : 0,\n          background: `radial-gradient(280px circle at ${spot.x}px ${spot.y}px, rgba(45, 212, 191, .18), transparent 70%)`,\n        }}\n      />\n      <div className=\"relative\">\n        <span className=\"grid size-11 place-items-center rounded-2xl bg-teal-500/10 text-teal-600 dark:text-teal-400\">\n          <RefreshCw aria-hidden className=\"size-5\" />\n        </span>\n        <h3 className=\"mt-5 text-lg font-semibold text-zinc-900 dark:text-white\">Realtime sync</h3>\n        <p className=\"mt-2 text-sm leading-6 text-zinc-600 dark:text-zinc-400\">\n          Every edit lands on all devices in under 50 ms, even when your team works offline.\n        </p>\n        <dl className=\"mt-6 grid grid-cols-2 gap-3\">\n          {[['Latency', '42 ms'], ['Uptime', '99.99%']].map(([label, value]) => (\n            <div key={label} className=\"rounded-2xl border border-zinc-200 px-4 py-3 dark:border-zinc-800\">\n              <dt className=\"text-xs text-zinc-500 dark:text-zinc-400\">{label}</dt>\n              <dd className=\"mt-1 font-semibold text-zinc-900 dark:text-white\">{value}</dd>\n            </div>\n          ))}\n        </dl>\n      </div>\n    </article>\n  );\n}",
  "stat-card": "import { TrendingUp } from 'lucide-react';\n\nconst points = [12, 18, 15, 22, 20, 28, 26, 34, 31, 40, 38, 46];\n\nexport function StatCard() {\n  const max = Math.max(...points);\n  const line = points.map((value, index) => `${(index / (points.length - 1)) * 100},${40 - (value / max) * 36}`).join(' ');\n\n  return (\n    <article className=\"w-full max-w-xs rounded-3xl border border-zinc-200 bg-white p-5 shadow-sm dark:border-zinc-800 dark:bg-zinc-950\">\n      <div className=\"flex items-start justify-between gap-3\">\n        <div>\n          <p className=\"text-sm text-zinc-500 dark:text-zinc-400\">Monthly revenue</p>\n          <p className=\"mt-1 text-3xl font-semibold tracking-tight text-zinc-900 dark:text-white\">$48.2k</p>\n        </div>\n        <span className=\"inline-flex items-center gap-1 rounded-full bg-emerald-500/10 px-2.5 py-1 text-xs font-semibold text-emerald-700 dark:text-emerald-400\">\n          <TrendingUp aria-hidden className=\"size-3.5\" /> +18.4%\n        </span>\n      </div>\n      <svg viewBox=\"0 0 100 40\" preserveAspectRatio=\"none\" className=\"mt-5 h-16 w-full\" role=\"img\" aria-label=\"Revenue trending up over 12 months\">\n        <defs>\n          <linearGradient id=\"stat-card-fill\" x1=\"0\" x2=\"0\" y1=\"0\" y2=\"1\">\n            <stop offset=\"0\" stopColor=\"#14b8a6\" stopOpacity=\".28\" />\n            <stop offset=\"1\" stopColor=\"#14b8a6\" stopOpacity=\"0\" />\n          </linearGradient>\n        </defs>\n        <polygon points={`0,40 ${line} 100,40`} fill=\"url(#stat-card-fill)\" />\n        <polyline points={line} fill=\"none\" stroke=\"#14b8a6\" strokeWidth=\"1.6\" vectorEffect=\"non-scaling-stroke\" strokeLinejoin=\"round\" />\n      </svg>\n      <div className=\"mt-4 flex justify-between text-xs text-zinc-500 dark:text-zinc-400\">\n        <span>Jan</span>\n        <span>vs. last month</span>\n        <span>Dec</span>\n      </div>\n    </article>\n  );\n}",
  "text-rotate": "'use client';\nimport { useEffect, useState } from 'react';\n\nconst words = ['interfaces', 'dashboards', 'landing pages', 'AI agents'];\n\nexport function TextRotate() {\n  const [index, setIndex] = useState(0);\n\n  useEffect(() => {\n    if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;\n    const timer = window.setInterval(() => setIndex((value) => (value + 1) % words.length), 2200);\n    return () => window.clearInterval(timer);\n  }, []);\n\n  return (\n    <>\n      <style>{`@keyframes pui-rise{from{opacity:0;transform:translateY(60%);filter:blur(6px)}to{opacity:1;transform:none;filter:none}}`}</style>\n      <h2 className=\"text-center text-3xl font-semibold tracking-tight text-zinc-900 sm:text-5xl dark:text-white\">\n        <span className=\"sr-only\">Build beautiful interfaces, dashboards, landing pages and AI agents.</span>\n        <span aria-hidden>\n          Build beautiful\n          <span className=\"mt-1 block overflow-hidden pb-1\">\n            <span\n              key={words[index]}\n              className=\"inline-block bg-gradient-to-r from-teal-500 to-violet-500 bg-clip-text text-transparent motion-safe:animate-[pui-rise_.5s_cubic-bezier(.22,1,.36,1)]\"\n            >\n              {words[index]}\n            </span>\n          </span>\n        </span>\n      </h2>\n    </>\n  );\n}",
  "theme-switch": "'use client';\nimport { Moon, Sun } from 'lucide-react';\nimport { useState } from 'react';\n\nexport function ThemeSwitch() {\n  const [night, setNight] = useState(false);\n\n  return (\n    <button\n      type=\"button\"\n      role=\"switch\"\n      aria-checked={night}\n      aria-label=\"Dark mode\"\n      onClick={() => setNight((value) => !value)}\n      className={`relative h-12 w-24 overflow-hidden rounded-full p-1 shadow-inner transition-colors duration-500 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-violet-500 focus-visible:ring-offset-2 dark:focus-visible:ring-offset-zinc-950 ${\n        night ? 'bg-indigo-950' : 'bg-sky-300'\n      }`}\n    >\n      {/* Stars fade in at night, a cloud drifts by during the day. */}\n      <span aria-hidden className={`absolute inset-0 transition-opacity duration-500 ${night ? 'opacity-100' : 'opacity-0'}`}>\n        {[[18, 12], [30, 28], [44, 16], [24, 36]].map(([left, top]) => (\n          <span key={`${left}-${top}`} className=\"absolute size-1 rounded-full bg-white\" style={{ left, top }} />\n        ))}\n      </span>\n      <span aria-hidden className={`absolute right-3 top-3 h-3 w-7 rounded-full bg-white/80 transition-all duration-500 ${night ? 'translate-x-6 opacity-0' : 'opacity-100'}`} />\n      <span\n        className={`relative grid size-10 place-items-center rounded-full shadow-md transition-all duration-500 ease-[cubic-bezier(.34,1.56,.64,1)] ${\n          night ? 'translate-x-12 bg-zinc-200 text-indigo-950' : 'translate-x-0 bg-amber-300 text-amber-700'\n        }`}\n      >\n        {night ? <Moon aria-hidden className=\"size-5\" /> : <Sun aria-hidden className=\"size-5\" />}\n      </span>\n    </button>\n  );\n}",
};
